import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Modal from 'react-bootstrap/Modal';
import Button from 'react-bootstrap/Button';
import Container from 'react-bootstrap/Container';
import Row from 'react-bootstrap/Row';
import Col from 'react-bootstrap/Col';
import Image from 'react-bootstrap/Image';
import Form from 'react-bootstrap/Form';
import './Login.scss';

function Register() {
  const navigate = useNavigate();
  
  // State to track selected role; default to "USER"
  const [role, setRole] = useState("USER");
  // State to control modal visibility
  const [showModal, setShowModal] = useState(true);
  
  // State objects for form data for user and professional
  const [userData, setUserData] = useState({
    username: "",
    email: "",
    password: ""
  });
  const [professionalData, setProfessionalData] = useState({
    name: "",
    email: "",
    password: ""
  });
  
  // Handle changes in role selection (radio buttons in modal)
  const handleRoleChange = (e) => {
    setRole(e.target.value);
  };
  
  // Close the modal when the confirm button is clicked
  const handleModalConfirm = () => {
    setShowModal(false);
  };

  // Handlers for form field changes for each role
  const handleUserChange = (e) => {
    const { name, value } = e.target;
    setUserData(prev => ({ ...prev, [name]: value }));
  };

  const handleProfessionalChange = (e) => {
    const { name, value } = e.target;
    setProfessionalData(prev => ({ ...prev, [name]: value }));
  };

  // Handle form submission; sends data to the corresponding endpoint
  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (role === "USER") {
      try {
        const response = await fetch("http://localhost:6543/api/register", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(userData),
        });
        if (!response.ok) {
          throw new Error("User registration failed");
        }
        const result = await response.json();
        alert("User registered successfully!");
        navigate("/");
      } catch (error) {
        alert("Error: " + error.message);
      }
    } else if (role === "PROFESSIONAL") {
      try {
        const response = await fetch("http://localhost:6543/api/register/professional", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(professionalData),
        });
        if (!response.ok) {
          throw new Error("Professional registration failed");
        }
        const result = await response.text();
        alert(result);
        navigate("/");
      } catch (error) {
        alert("Error: " + error.message);
      }
    }
  };

  const boyIcon = require('./assets/icons/boy.png');
  const professionalIcon = require('./assets/icons/business-woman.png');
  const eunoiaLogo = require('./assets/icons/eunoia_ver2.png');

  return (
    <div className='registerBackground'>
      {/* Role selection modal */}
      <Modal show={showModal} onHide={handleModalConfirm} backdrop="static" keyboard={false} style={{userSelect:"none"}}>
        <Modal.Header style={{background:"#3674B5"}}>
          <Modal.Title style={{color:"#E0F4FF", fontFamily:"font1"}}>Register As</Modal.Title>
        </Modal.Header>
        <Modal.Body style={{background:"#A1E3F9"}}>
          <Container class="grid-wrapper grid-col-auto">
            <Row>
              <Col xs={6}>
              <center>
                  <label for="radio-card-1" class="radio-card">
                    <input
                    name="radio-card"
                    id="radio-card-1"
                    type="radio"
                    value="USER"
                    checked={role === "USER"}
                    onChange={handleRoleChange}/>
                    <div class="card-content-wrapper">
                      <span class="check-icon"></span>
                      <div class="card-content">
                        <Image
                          width={200}
                          height={200}
                          src={boyIcon}
                          alt="User Icon"
                          fluid
                        />
                        <h2>User</h2>
                        <h5>Experience Eunoia with others</h5>
                      </div>
                    </div>
                  </label>
                </center>
                </Col>
                <Col xs={6}>
                <center>
                <label for="radio-card-2" class="radio-card">
                  <input
                  name="radio-card"
                  id="radio-card-2"
                  type="radio"
                  value="PROFESSIONAL"
                  checked={role === "PROFESSIONAL"}
                  onChange={handleRoleChange}/>
                  <div class="card-content-wrapper">
                    <span class="check-icon"></span>
                    <div class="card-content">
                      <Image
                          width={200}
                          height={200}
                          src={professionalIcon}
                          alt="Professional Icon"
                          fluid
                        />
                      <h2>Professional</h2>
                      <h5>Offer your services to Eunoia</h5>
                    </div>
                  </div>
                </label>
                </center>
                </Col>
            </Row>
          </Container>
        </Modal.Body>
        <Modal.Footer style={{background:"#3674B5"}}>
          <Button variant="primary" onClick={handleModalConfirm} className="registerRadioConfirm">Confirm</Button>
        </Modal.Footer>
      </Modal>

      {/* Registration Form */}
      <center>
        <Container className="container-md registerContainer" fluid>
          <Row className="justify-content-md-center">
            <Col>
              <Image src={eunoiaLogo} className="img-fluid" alt="Your Company" style={{height: "30%",width: "24%",display: "block",margin:"30px"}} />
              <h2 style={{fontFamily:"font2", marginBottom:"20px"}}>Register</h2>
              <Form onSubmit={handleSubmit}>
                {role === "USER" ? (
                  <>
                    <Form.Group>
                      <Form.Label>Username</Form.Label>
                        <Form.Control 
                          type="text" 
                          name="username" 
                          placeholder="Username" 
                          value={userData.username} 
                          onChange={handleUserChange} 
                          required 
                        />
                    </Form.Group>
                    <Form.Group>
                      <Form.Label>Email address</Form.Label>
                        <Form.Control 
                          type="email" 
                          name="email" 
                          placeholder="Email" 
                          value={userData.email} 
                          onChange={handleUserChange} 
                          required 
                        />
                    </Form.Group>
                    <Form.Group>
                      <Form.Label>Password</Form.Label>
                        <Form.Control  
                          type="password" 
                          name="password" 
                          placeholder="Password" 
                          value={userData.password} 
                          onChange={handleUserChange} 
                          required 
                        />
                    </Form.Group>
                  </>
                ) : (
                  <>
                    <Form.Group>
                      <Form.Label>Full Name</Form.Label>
                        <Form.Control
                          type="text" 
                          name="name" 
                          placeholder="Full Name" 
                          value={professionalData.name} 
                          onChange={handleProfessionalChange} 
                          required 
                        />
                    </Form.Group>
                    <Form.Group>
                      <Form.Label>Email address</Form.Label>
                        <Form.Control 
                          type="email" 
                          name="email" 
                          placeholder="Email" 
                          value={professionalData.email} 
                          onChange={handleProfessionalChange} 
                          required 
                        />
                    </Form.Group>
                    <Form.Group>
                      <Form.Label>Password</Form.Label>
                        <Form.Control
                          type="password" 
                          name="password" 
                          placeholder="Password" 
                          value={professionalData.password} 
                          onChange={handleProfessionalChange} 
                          required 
                        />
                    </Form.Group>
                  </>
                )}
                <div>
                  <button type="submit">Register</button>
                </div>
              </Form>
              <div>
                <a href="/">Already have an account? Log in</a>
              </div>
            </Col>
          </Row>
        </Container>
      </center>
    </div>
  );
}

export default Register;


